import React, { useState, useEffect } from 'react';

// Estilos de cores profissionais
const COLORS = {
  primary: '#2563eb',
  secondary: '#64748b',
  success: '#10b981',
  danger: '#ef4444',
  bg: '#f8fafc',
  card: '#ffffff',
  text: '#1e293b'
};

export default function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [processos, setProcessos] = useState(() => {
    const salvo = localStorage.getItem('lexpro_data');
    return salvo ? JSON.parse(salvo) : [];
  });

  useEffect(() => {
    localStorage.setItem('lexpro_data', JSON.stringify(processos));
  }, [processos]);

  // Estatísticas do Dashboard
  const stats = {
    total: processos.length,
    urgentes: processos.filter(p => p.status === 'Urgente').length,
    honorarios: processos.reduce((acc, p) => acc + (Number(p.valor) || 0), 0)
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: COLORS.bg, fontFamily: '"Inter", sans-serif' }}>
      
      {/* SIDEBAR LATERAL - ESTILO PREMIUM */}
      <nav style={s.sidebar}>
        <div style={s.logo}>LEX<span>PRO</span></div>
        <div style={s.navItem(activeTab === 'dashboard')} onClick={() => setActiveTab('dashboard')}>📊 Dashboard</div>
        <div style={s.navItem(activeTab === 'processos')} onClick={() => setActiveTab('processos')}>📁 Processos</div>
        <div style={s.navItem(activeTab === 'financeiro')} onClick={() => setActiveTab('financeiro')}>💰 Financeiro</div>
        <div style={{ marginTop: 'auto', padding: '20px', fontSize: '12px', opacity: 0.5 }}>v 2.0.4</div>
      </nav>

      {/* CONTEÚDO PRINCIPAL */}
      <main style={{ flex: 1, padding: '40px', overflowY: 'auto' }}>
        
        <header style={s.header}>
          <div>
            <h1 style={{ margin: 0, fontSize: '28px' }}>Olá, Dr. Rodrigo</h1>
            <p style={{ color: COLORS.secondary }}>Seu escritório tem {stats.urgentes} prazos críticos hoje.</p>
          </div>
          <button style={s.btnPrimary} onClick={() => setActiveTab('processos')}>+ Novo Processo</button>
        </header>

        {activeTab === 'dashboard' && (
          <div style={s.bentoGrid}>
            <div style={s.statCard}>
              <span>Processos Ativos</span>
              <h2>{stats.total}</h2>
            </div>
            <div style={{ ...s.statCard, borderLeft: `4px solid ${COLORS.danger}` }}>
              <span>Prazos Críticos</span>
              <h2 style={{ color: COLORS.danger }}>{stats.urgentes}</h2>
            </div>
            <div style={{ ...s.statCard, borderLeft: `4px solid ${COLORS.success}` }}>
              <span>Receita Prevista</span>
              <h2 style={{ color: COLORS.success }}>R$ {stats.honorarios.toLocaleString()}</h2>
            </div>

            {/* GRÁFICO SIMULADO / LISTA RÁPIDA */}
            <div style={{ ...s.card, gridColumn: 'span 3' }}>
              <h3 style={{ marginTop: 0 }}>Atividades Recentes</h3>
              {processos.slice(0, 3).map(p => (
                <div key={p.id} style={s.recentItem}>
                  <span>{p.cliente}</span>
                  <span style={s.badge(p.status)}>{p.status}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'processos' && (
          <div style={s.card}>
            <h3>Gestão de Casos</h3>
            <p>Cadastre e gerencie os processos ativos no tribunal.</p>
            {/* Aqui você pode inserir o formulário que já tínhamos, mas com esse novo visual */}
            <p style={{opacity: 0.5}}>Módulo de cadastro avançado carregando...</p>
          </div>
        )}
      </main>
    </div>
  );
}

// ESTILOS DE UI DE ALTO NÍVEL
const s = {
  sidebar: {
    width: '260px',
    backgroundColor: '#0f172a',
    color: '#fff',
    display: 'flex',
    flexDirection: 'column',
    padding: '30px 0'
  },
  logo: {
    padding: '0 30px 40px',
    fontSize: '22px',
    fontWeight: '800',
    letterSpacing: '1px',
    color: COLORS.primary
  },
  navItem: (active) => ({
    padding: '15px 30px',
    cursor: 'pointer',
    backgroundColor: active ? '#1e293b' : 'transparent',
    borderLeft: active ? `4px solid ${COLORS.primary}` : '4px solid transparent',
    transition: '0.3s',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    fontSize: '15px'
  }),
  header: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '40px'
  },
  btnPrimary: {
    backgroundColor: COLORS.primary,
    color: 'white',
    border: 'none',
    padding: '12px 24px',
    borderRadius: '8px',
    fontWeight: '600',
    cursor: 'pointer',
    boxShadow: '0 4px 10px rgba(37, 99, 235, 0.2)'
  },
  bentoGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(3, 1fr)',
    gap: '25px'
  },
  statCard: {
    backgroundColor: '#fff',
    padding: '25px',
    borderRadius: '16px',
    boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)',
    display: 'flex',
    flexDirection: 'column'
  },
  card: {
    backgroundColor: '#fff',
    padding: '30px',
    borderRadius: '16px',
    boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05)'
  },
  recentItem: {
    display: 'flex',
    justifyContent: 'space-between',
    padding: '15px 0',
    borderBottom: '1px solid #f1f5f9'
  },
  badge: (status) => ({
    padding: '4px 12px',
    borderRadius: '20px',
    fontSize: '12px',
    fontWeight: 'bold',
    backgroundColor: status === 'Urgente' ? '#fee2e2' : '#dcfce7',
    color: status === 'Urgente' ? COLORS.danger : COLORS.success
  })
};
